document.addEventListener("DOMContentLoaded", () => {
    initDashboardMetrics();
    renderAllTables();
    setupNavigation();
    setupFilters();
    setupModalClose();
});

function setupNavigation() {
    const navButtons = document.querySelectorAll(".nav-btn");
    const tabContents = document.querySelectorAll(".tab-content");
    navButtons.forEach(btn => {
        btn.addEventListener("click", () => {
            const targetId = btn.getAttribute("data-target");
            navButtons.forEach(b => b.classList.remove("active"));
            tabContents.forEach(tc => tc.classList.remove("active"));
            btn.classList.add("active");
            document.getElementById(targetId).classList.add("active");
        });
    });
}

function initDashboardMetrics() {
    document.getElementById("count-high-actors").innerText = ontologyData.actors.filter(a => a.isHighRisk).length;
    document.getElementById("count-critical-cve").innerText = ontologyData.vulnerabilities.filter(v => v.type === "Critical_Vulnerability").length;
    document.getElementById("count-inferred-triples").innerText = "+" + (ontologyData.vulnerabilities.length + ontologyData.actors.length);
}

function renderAllTables() {
    renderActorsTable(ontologyData.actors);
    renderMalwareTable(ontologyData.malware);
    renderSoftwareTable(ontologyData.software);
    renderVulnerabilitiesTable(ontologyData.vulnerabilities);
}

function renderActorsTable(data) {
    const tbody = document.querySelector("#table-actors tbody");
    tbody.innerHTML = "";
    
    data.forEach(actor => {
        const softTexto = actor.softwares.length > 0 ? actor.softwares.join(", ") : "Ninguno";
        
        // Formatear técnicas en una lista limpia hacia abajo
        const techTexto = actor.techniques.length > 0 
            ? actor.techniques.map(t => `<div>• ${t}</div>`).join("") 
            : "<div>Ninguna registrada</div>";
            
        const cvesTexto = actor.cves.length > 0 ? actor.cves.join(", ") : "Ninguno (No explota CVSS Críticos)";
        
        // Clasificación lógica basada en el razonador Pellet
        const badgeClasificacion = actor.isHighRisk 
            ? '<span class="badge badge-red">High_Risk_Threat_Actor</span>' 
            : '<span class="badge badge-metal">Threat_Actor (Base)</span>';
            
        // Mensaje personalizado para la ventana modal dependiendo de la auditoría del actor
        const reglaExplicacion = actor.isHighRisk
            ? `[INFERENCIA SWRL ACTIVADA]\n\nClase: High_Risk_Threat_Actor\n\nRegla:\nThreat_Actor(?a) ^ actor_uses_technique(?a, ?t) ^ High_Impact_Technique(?t) -> High_Risk_Threat_Actor(?a)\n\nJustificación lógica:\nPellet ha catalogado a ${actor.name} en esta categoría superior debido a que el grafo demuestra su vinculación operativa con técnicas que explotan vulnerabilidades de nivel crítico.`
            : `[CONSULTA CLASE BASE]\n\nClase: Threat_Actor (Estándar)\n\nEl individuo ${actor.name} se encuentra indexado correctamente en la taxonomía jerárquica de la ontología, no cumpliendo actualmente los requisitos del axioma de riesgo crítico SWRL.`;

        const tr = document.createElement("tr");
        tr.innerHTML = `
            <td><strong>${actor.name}</strong></td>
            <td>
                <div style="margin-bottom: 8px;"><small style='color:var(--neon-blue); font-weight:bold;'>🛠️ SOFTWARE ASOCIADO:</small><br><span style="color:#a0aec0;">${softTexto}</span></div>
                <div><small style='color:var(--neon-amber); font-weight:bold;'>⚡ TÉCNICAS MITRE:</small><br><span style="color:#e2e8f0; font-size:11px;">${techTexto}</span></div>
            </td>
            <td><span class="text-blue" style="font-family:'Fira Code', monospace; font-size:12px;">${cvesTexto}</span></td>
            <td>${badgeClasificacion}</td>
            <td><button class="action-btn" onclick="openTraceModal('${actor.id}', \`${reglaExplicacion}\`)">Ver Regla</button></td>
        `;
        tbody.appendChild(tr);
    });
}

function renderMalwareTable(data) {
    const tbody = document.querySelector("#table-malware tbody");
    if(!tbody) return;
    tbody.innerHTML = "";
    data.forEach(m => {
        const tr = document.createElement("tr");
        tr.innerHTML = `<td><span class="text-red">☣️ ${m.name}</span></td><td><span class="badge badge-amber">${m.type}</span></td><td>${m.techniques}</td><td>${m.cves}</td><td><button class="action-btn" onclick="openTraceModal('${m.name}', '${m.trace}')">Trazar Grafo</button></td>`;
        tbody.appendChild(tr);
    });
}

function renderSoftwareTable(data) {
    const tbody = document.querySelector("#table-software tbody");
    if(!tbody) return;
    tbody.innerHTML = "";
    data.forEach(s => {
        const tr = document.createElement("tr");
        tr.innerHTML = `<td><span class="text-blue">🛠️ ${s.name}</span></td><td>${s.actor}</td><td>${s.techniques}</td><td>${s.cves}</td><td><button class="action-btn" onclick="openTraceModal('${s.name}', '${s.trace}')">Trazar Grafo</button></td>`;
        tbody.appendChild(tr);
    });
}

function renderVulnerabilitiesTable(data) {
    const tbody = document.querySelector("#table-vulnerabilities tbody");
    if(!tbody) return;
    tbody.innerHTML = "";
    data.forEach(v => {
        const tr = document.createElement("tr");
        tr.innerHTML = `<td><strong>${v.cve}</strong></td><td style="font-size:12px; color: #8a99ad;">${v.desc}</td><td><span class="badge badge-blue">${v.severity}</span></td><td><span class="text-yellow">${v.cwe}</span></td><td><span class="badge badge-metal">Analizada</span></td>`;
        tbody.appendChild(tr);
    });
}

function setupFilters() {
    const searchInput = document.getElementById("search-actors");
    if(searchInput) {
        searchInput.addEventListener("input", (e) => {
            const val = e.target.value.toLowerCase();
            const filtered = ontologyData.actors.filter(a => a.name.toLowerCase().includes(val));
            renderActorsTable(filtered);
        });
    }
}

function openTraceModal(title, traceMessage) {
    document.getElementById("modal-title").innerText = "[AUDITORÍA SEMÁNTICA]: " + title.toUpperCase();
    document.getElementById("modal-trace").innerText = traceMessage;
    document.getElementById("cyber-modal").classList.add("active");
}

function setupModalClose() {
    const modal = document.getElementById("cyber-modal");
    const closeBtn = document.getElementById("close-modal-btn");
    if(closeBtn) closeBtn.addEventListener("click", () => modal.classList.remove("active"));
    window.addEventListener("click", (e) => { if (e.target === modal) modal.classList.remove("active"); });
}
